_spline = CubicSpline.construct_fast(_coeffs, _knots)

def get_Bpol(position):
    """
    Get Bpol value at given position(s).

    Parameters:
    -----------
    position : float or array
        Position along Spar coordinate

    Returns:
    --------
    field_value : float or array
        Bpol at the given position(s)
    """
    result = _spline(position)
    return np.clip(result, 0, None)  # Ensure non-negative

def get_field_range():
    """Return the valid range of Spar coordinates."""
    return (_knots[0], _knots[-1])

